                    );
                    // The rejected value must never be quoted back.
                    assert!(
                        !msg.contains("trailing"),
                        "text {text:?}: parser internals must not leak: {msg}"
                    );
                }
                Ok(v) => panic!("text {text:?}: expected rejection, got {v:?}"),
            }
        }
